using System.Collections.Generic;
using System.IO;

namespace Ros.Config
{
    public partial class ConfigManager
    {
        public Dictionary<int, card_gain_upgrade> card_gain_upgradeData;
        public card_gain_upgrade Getcard_gain_upgradeConfig(int key)
        {
            return ConfigBinary.Require(card_gain_upgradeData, key, "card_gain_upgrade");
        }
        private void Loadcard_gain_upgradeConfig()
        {
            using (BinaryReader r = ConfigBinary.Open("card_gain_upgrade"))
            {
                int count = r.ReadInt32();
                card_gain_upgradeData = new Dictionary<int, card_gain_upgrade>(count);
                for (int i = 0; i < count; i++)
                {
                    card_gain_upgrade row;
                    row.key = r.ReadInt32();
                    row.postUpgradeLevelSingleDigit = r.ReadInt32();
                    row.silverCardWeight = r.ReadInt32();
                    row.GoldCardWeight = r.ReadInt32();
                    row.ColourfulCardWeight = r.ReadInt32();
                    card_gain_upgradeData.Add(row.key, row);
                }
            }
        }
    }
    public struct card_gain_upgrade
    {
        public int key;  // 主键
        public int postUpgradeLevelSingleDigit;  // 升级后的等级的个位数
        public int silverCardWeight;  // 白银卡权重
        public int GoldCardWeight;  // 黄金卡权重
        public int ColourfulCardWeight;  // 炫彩卡权重
    }
